<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_permission('content.manage');$pdo=db();
$tabs=['areas'=>['service_areas','Áreas de servicio'],'tips'=>['tips','Tips'],'videos'=>['videos','Videos']];$tab=(string)($_GET['tab']??'areas');if(!isset($tabs[$tab]))$tab='areas';[$table,$label]=$tabs[$tab];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='delete'){$pdo->prepare("DELETE FROM $table WHERE id=?")->execute([$id]);flash('success',$label.' eliminado.');}else{if($tab==='areas'){$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Escribe el nombre del área.');$vals=[$name,rich_text_sanitize((string)($_POST['description']??'')),(int)$_POST['sort_order'],isset($_POST['active'])?1:0];$sql=$id?'UPDATE service_areas SET name=?,description=?,sort_order=?,active=? WHERE id=?':'INSERT INTO service_areas(name,description,sort_order,active) VALUES(?,?,?,?)';if($id)$vals[]=$id;$pdo->prepare($sql)->execute($vals);}elseif($tab==='tips'){$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('Escribe el título.');$vals=[$title,rich_text_sanitize((string)($_POST['body']??'')),(int)$_POST['sort_order'],isset($_POST['active'])?1:0];$sql=$id?'UPDATE tips SET title=?,body=?,sort_order=?,active=? WHERE id=?':'INSERT INTO tips(title,body,sort_order,active) VALUES(?,?,?,?)';if($id)$vals[]=$id;$pdo->prepare($sql)->execute($vals);}else{$title=trim((string)$_POST['title']);$url=trim((string)$_POST['video_url']);if($title===''||$url==='')throw new RuntimeException('Completa título y URL.');$vals=[$title,$url,(int)$_POST['sort_order'],isset($_POST['active'])?1:0];$sql=$id?'UPDATE videos SET title=?,video_url=?,sort_order=?,active=? WHERE id=?':'INSERT INTO videos(title,video_url,sort_order,active) VALUES(?,?,?,?)';if($id)$vals[]=$id;$pdo->prepare($sql)->execute($vals);}flash('success',$label.' guardado.');}header('Location: extras.php?tab='.$tab);exit;}catch(Throwable $e){flash('error',$e->getMessage());header('Location: extras.php?tab='.$tab);exit;}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM $table WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query("SELECT * FROM $table ORDER BY sort_order,id")->fetchAll();$pageTitle='Areas · Tips · Videos';$active='extras';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">CONTENIDO EXTRA</p><h1><?=h($label)?></h1><p class="muted">Administra información complementaria sin modificar código.</p></div><div class="actions"><?php foreach($tabs as $k=>$v):?><a class="button <?=$tab===$k?'':'secondary'?>" href="?tab=<?=$k?>"><?=h($v[1])?></a><?php endforeach;?></div></div><section class="panel"><h2><?=$edit?'Editar':'Agregar'?> <?=h(rtrim($label,'s'))?></h2><form class="crud-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><?php if($tab==='areas'):?><label>Nombre<input name="name" value="<?=h($edit['name']??'')?>" required></label><label>Orden<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label><label class="full">Descripción<textarea name="description"><?=h($edit['description']??'')?></textarea></label><?php elseif($tab==='tips'):?><label>Título<input name="title" value="<?=h($edit['title']??'')?>" required></label><label>Orden<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label><label class="full">Contenido<textarea name="body"><?=h($edit['body']??'')?></textarea></label><?php else:?><label>Título<input name="title" value="<?=h($edit['title']??'')?>" required></label><label>Orden<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label><label class="full">URL del video<input type="url" name="video_url" value="<?=h($edit['video_url']??'')?>" required></label><?php endif;?><label class="status-field"><span class="field-label">Estado</span><span class="check-control"><input type="checkbox" name="active" <?=!$edit||(int)$edit['active']===1?'checked':''?>><span>Activo</span></span></label><div class="full form-actions"><button>Guardar</button><?php if($edit):?><a class="button secondary" href="?tab=<?=$tab?>">Cancelar</a><?php endif;?></div></form></section><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Orden</th><th>Contenido</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['sort_order']?></td><td><strong><?=h($r['name']??$r['title']??'')?></strong><br><small><?=h(rich_text_plain((string)($r['description']??$r['body']??$r['video_url']??'')))?></small></td><td><span class="badge <?=$r['active']?'active':''?>"><?=$r['active']?'Activo':'Oculto'?></span></td><td><div class="actions"><a class="button secondary small" href="?tab=<?=$tab?>&edit=<?=$r['id']?>">Editar</a><form method="post" data-premium-confirm data-confirm-title="Eliminar registro" data-confirm-message="¿Eliminar este registro? Esta acción no se puede deshacer." data-confirm-ok="Sí, eliminar" data-confirm-cancel="Cancelar"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger small">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>
